    24  void
    25  UA_Notification_enqueue(UA_Server *server, UA_Subscription *sub,
    26                          UA_MonitoredItem *mon, UA_Notification *n) {
    27      /* Add to the MonitoredItem */
    28      TAILQ_INSERT_TAIL(&mon->queue, n, listEntry);
    29      ++mon->queueSize;
    30
    31      /* Add to the subscription */
    32      TAILQ_INSERT_TAIL(&sub->notificationQueue, n, globalEntry);
    33      ++sub->notificationQueueSize;
    34      if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_CHANGENOTIFY) {
    35          ++sub->dataChangeNotifications;
    36      } else if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_EVENTNOTIFY) {
    37          ++sub->eventNotifications;
    38      } else if(mon->monitoredItemType == UA_MONITOREDITEMTYPE_STATUSNOTIFY) {
    39          ++sub->statusChangeNotifications;
    40      }
    41
    42      /* Ensure enough space is available in the MonitoredItem. Do this only after
    43       * adding the new Notification. */
    44      UA_MonitoredItem_ensureQueueSpace(server, mon);
    45  }
