    93  void
    94  UA_Subscription_deleteMembers(UA_Server *server, UA_Subscription *sub) {
    95      UA_LOG_DEBUG_SESSION(server->config.logger, sub->session, "Subscription %u | "
    96                               "Delete the subscription", sub->subscriptionId);
    97
    98      Subscription_unregisterPublishCallback(server, sub);
    99
   100      /* Delete monitored Items */
   101      UA_MonitoredItem *mon, *tmp_mon;
   102      LIST_FOREACH_SAFE(mon, &sub->monitoredItems, listEntry, tmp_mon) {
   103          LIST_REMOVE(mon, listEntry);
   104          UA_MonitoredItem_delete(server, mon);
   105      }
   106      sub->monitoredItemsSize = 0;
   107
   108      /* Delete Retransmission Queue */
   109      UA_NotificationMessageEntry *nme, *nme_tmp;
   110      TAILQ_FOREACH_SAFE(nme, &sub->retransmissionQueue, listEntry, nme_tmp) {
   111          TAILQ_REMOVE(&sub->retransmissionQueue, nme, listEntry);
   112          UA_NotificationMessage_deleteMembers(&nme->message);
   113          UA_free(nme);
   114      }
   115      sub->retransmissionQueueSize = 0;
   116  }
