   118  UA_MonitoredItem *
   119  UA_Subscription_getMonitoredItem(UA_Subscription *sub, UA_UInt32 monitoredItemId) {
   120      UA_MonitoredItem *mon;
   121      LIST_FOREACH(mon, &sub->monitoredItems, listEntry) {
   122          if(mon->monitoredItemId == monitoredItemId)
   123              break;
   124      }
   125      return mon;
   126  }
