   156  static void
   157  UA_Subscription_addRetransmissionMessage(UA_Server *server, UA_Subscription *sub,
   158                                           UA_NotificationMessageEntry *entry) {
   159      /* Release the oldest entry if there is not enough space */
   160      if(server->config.maxRetransmissionQueueSize > 0 &&
   161         sub->retransmissionQueueSize >= server->config.maxRetransmissionQueueSize) {
   162          UA_NotificationMessageEntry *lastentry =
   163              TAILQ_LAST(&sub->retransmissionQueue, ListOfNotificationMessages);
   164          TAILQ_REMOVE(&sub->retransmissionQueue, lastentry, listEntry);
   165          --sub->retransmissionQueueSize;
   166          UA_NotificationMessage_deleteMembers(&lastentry->message);
   167          UA_free(lastentry);
   168      }
   169
   170      /* Add entry */
   171      TAILQ_INSERT_TAIL(&sub->retransmissionQueue, entry, listEntry);
   172      ++sub->retransmissionQueueSize;
   173  }
