   120  void
   121  UA_SecureChannel_deleteMembersCleanup(UA_SecureChannel *channel) {
   122      /* Delete members */
   123      UA_ByteString_deleteMembers(&channel->remoteCertificate);
   124      UA_ByteString_deleteMembers(&channel->localNonce);
   125      UA_ByteString_deleteMembers(&channel->remoteNonce);
   126      UA_ChannelSecurityToken_deleteMembers(&channel->securityToken);
   127      UA_ChannelSecurityToken_deleteMembers(&channel->nextSecurityToken);
   128
   129      /* Delete the channel context for the security policy */
   130      if(channel->securityPolicy)
   131          channel->securityPolicy->channelModule.deleteContext(channel->channelContext);
   132
   133      /* Detach from the connection and close the connection */
   134      if(channel->connection) {
   135          if(channel->connection->state != UA_CONNECTION_CLOSED)
   136              channel->connection->close(channel->connection);
   137          UA_Connection_detachSecureChannel(channel->connection);
   138      }
   139
   140      /* Remove session pointers (not the sessions) and NULL the pointers back to
   141       * the SecureChannel in the Session */
   142      UA_SessionHeader *sh, *temp;
   143      LIST_FOREACH_SAFE(sh, &channel->sessions, pointers, temp) {
   144          sh->channel = NULL;
   145          LIST_REMOVE(sh, pointers);
   146      }
   147
   148      /* Remove the buffered messages */
   149      UA_SecureChannel_deleteMessages(channel);
   150  }
