   129  static void
   130  initUaRegisterServer(UA_RegisteredServer *requestServer) {
   131      requestServer->isOnline = UA_TRUE;
   132      requestServer->serverUri = server->config.applicationDescription.applicationUri;
   133      requestServer->productUri = server->config.applicationDescription.productUri;
   134      requestServer->serverType = server->config.applicationDescription.applicationType;
   135      requestServer->gatewayServerUri = server->config.applicationDescription.gatewayServerUri;
   136
   137      // create the semaphore
   138      int fd = open("/tmp/open62541-corpus-semaphore", O_RDWR|O_CREAT, S_IRWXU | S_IRWXG | S_IRWXO);
   139      close(fd);
   140      requestServer->semaphoreFilePath = UA_STRING("/tmp/open62541-corpus-semaphore");
   141
   142      requestServer->serverNames = &server->config.applicationDescription.applicationName;
   143      requestServer->serverNamesSize = 1;
   144
   145      size_t nl_discurls = server->config.networkLayersSize;
   146      requestServer->discoveryUrls = (UA_String*)UA_malloc(sizeof(UA_String) * nl_discurls);
   147      requestServer->discoveryUrlsSize = nl_discurls;
   148      for(size_t i = 0; i < nl_discurls; ++i) {
   149          UA_ServerNetworkLayer *nl = &server->config.networkLayers[i];
   150          requestServer->discoveryUrls[i] = nl->discoveryUrl;
   151      }
   152
   153  }
