   155  static UA_StatusCode
   156  registerServerRequest(UA_Client *client) {
   157      /* Prepare the request. Do not cleanup the request after the service call,
   158       * as the members are stack-allocated or point into the server config. */
   159      UA_RegisterServerRequest request;
   160      UA_RegisterServerRequest_init(&request);
   161      /* Copy from RegisterServer2 request */
   162      request.requestHeader.timestamp = UA_DateTime_now();
   163      request.requestHeader.timeoutHint = 10000;
   164
   165      initUaRegisterServer(&request.server);
   166
   167
   168      UA_RegisterServerResponse response;
   169      UA_RegisterServerResponse_init(&response);
   170
   171      __UA_Client_Service(client, &request, &UA_TYPES[UA_TYPES_REGISTERSERVERREQUEST],
   172                          &response, &UA_TYPES[UA_TYPES_REGISTERSERVERRESPONSE]);
   173
   174      UA_free(request.server.discoveryUrls);
   175      ASSERT_GOOD(response.responseHeader.serviceResult);
   176
   177      return UA_STATUSCODE_GOOD;
   178  }
